def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """

    def decorator(func):
        if not inspect.isfunction(func):
            raise ValueError('The @mru_cache decorator must be applied innermost of all decorators.')

        if typed and not isinstance(func, (staticmethod, classmethod)):
            raise ValueError('The @mru_cache decorator only applies to static methods and class methods.')

        memoized_results = collections.OrderedDict(maxsize=maxsize)
        cache_id = id(func)

        @functools.wraps(func)
        def memoize(*args, **kwargs):
            key = (func.__name__, args, tuple(kwargs.items()))
            if key in memoized_results:
                result = memoized_results[key]
            else:
                result = func(*args, **kwargs)
                if len(memoized_results) >= maxsize:
                    memoized_results.popitem(last=False)
                memoized_results[key] = result
            return result

        def clear():
            memoized_results.clear()
        memoize.clear = clear

        def update(*args, **kwargs):
            key = (func.__name__, args, tuple(kwargs.items()))
            if key in memoized_results:
                memoized_results.pop(key)
            func(*args, **kwargs)
            return func(*args, **kwargs)

        memoize.update = update

        def get(*args, **kwargs):
            key = (func.__name__, args, tuple(kwargs.items()))
            return memoized_results.get(key)

        memoize.get = get

        return memoize

    return decorator

