def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    # Find the minimum base class by depth-first search
    class_minimum = None
    for base in classes:
        current_minimum = base
        while current_minimum and current_minimum.__bases__:
            current_minimum = current_minimum.__bases__[0]
        if not class_minimum or current_minimum.depth() < class_minimum.depth():
            class_minimum = current_minimum

    # Perform a depth-first traversal from the minimum class to create the minimal set
    def get_min_classes(node, depth):
        if not node:
            return []
        if depth > len(classes):
            return []
        if node in classes:
            return [node]
        if isinstance(node, type):
            return classes + get_min_classes(node.__bases__, depth + 1)
        return []

    minimal_set = get_min_classes(class_minimum, 0)

    # Sort the minimal set by depth or another attribute if provided
    if classes:
        minimal_set.sort(key=lambda x: x.depth())  # Default to depth

    return minimal_set

