def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    param_style = self.SQLParams.in_style if self.SQLParams.in_style and not isinstance(many_params, dict) else None

    for params in many_params:
        if param_style is None:
            raise ValueError("Parameter style is not specified")

        if isinstance(params, dict):
            # Prepare output parameters as a list of dictionaries
            out_params = [self.param_to_out_style(param, param_style) for param in params]
        else:
            # Prepare output parameters as a list of tuples
            out_params = [self.param_to_out_style(param, param_style) for param in params]

        matches = sql.split('?', maxsplit=len(out_params))
        formatted_sql = ''
        for i in range(len(matches)):
            if i < len(out_params):
                formatted_sql += matches[i] + str(out_params[i])
            else:
                formatted_sql += matches[i]

        many_params[i] = formatted_sql
    return formatted_sql, many_params

