def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if inventory is None:
        raise ValueError("Inventory cannot be None")
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    if extract_spec_version:
        if 'type' not in inventory:
            if self.spec_version:
                return inventory
            raise ValueError("Inventory does not contain a 'type' key")
        field_type = inventory['type']
        if not isinstance(field_type, Schema):
            raise ValueError(f"Unsupported 'type' value: {field_type}")
        return inventory

    if 'type' in inventory:
        field_type = inventory['type']
        if not isinstance(field_type, (Schema, Array, types.FunctionType)):
            raise ValueError(f"Unsupported field type: {field_type}")
        return inventory

    # No type value or unsupported type, use default self.spec_version
    if self.spec_version:
        return inventory
    raise ValueError("Inventory does not contain a 'type' key or unsupported field type")

