class PackageDataRetriever(PackageDataHandler):
    def __init__(self, zip_path: str, basename_extractor: XMLBasenameExtractor):
        self.zip_path = zip_path
        self.basename_extractor = basename_extractor

    def get_data_by_package(self, package_path: str) -> Dict[str, Optional[str]]:
        with zipfile.ZipFile(self.zip_path, 'r') as zip_ref:
            data_by_package: Dict[str, Optional[str]] = {}
            for name in zip_ref.namelist():
                full_path = os.path.join(package_path, name)
