def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        if not hasattr(re, "splitl"):
            # Fast Posix splitl function for Python older than 2.7
            def splitl(string, sep=b('\n')):
                if isinstance(string, bytes):
                    data = string
                else:
                    data = string.encode('utf8')
                result = []
                i = 0
                while i < len(data):
                    if data[i:i+len(sep)] == sep:
                        result.append(data[i:len(sep)])
                        i += len(sep)
                    elif i == len(data) - len(sep):
                        result.append(data[i:])
                        i += len(sep)
                    else:
                        i += 1
                return result
            re.splitl = splitl
        normfunc = re.splitl
    elif platform == 0:
        # Windows/CMD split workaround
        splitfunc = lambda x,sep,b=bytes([]): [x[idx+1:].replace(b,sep[idx],1).replace(b,sep[idx+1:],1) for idx in range(len(sep))]
    elif platform == 1:
        # Shlex on Posix
        import shlex
        splitfunc = shlex.split
    else:
        raise ValueError("Invalid platform value")

    return splitfunc(s)

