        return None
    try:
        if frequency.count("week") > 0:
            return datetime.timedelta( weeks= int(frequency.split(" ")[0]) )
        elif frequency.count("day") > 0:
            return datetime.timedelta( days= int(frequency.split(" ")[0]) )
        elif frequency.count("hour") > 0:
            return datetime.timedelta( hours= int(frequency.split(" ")[0]) )
        elif frequency.count("minute") > 0:
            return datetime.timedelta( minutes= int(frequency.split(" ")[0]) )
        elif frequency.count("second") > 0:
            return datetime.timedelta( seconds= int(frequency.split(" ")[0]) )
        else:
            raise ValueError("Unrecognised frequency '%s'" % frequency)
    except ValueError as e:
        raise ValueError("Invalid frequency '%s'" % frequency )

