def popitem(self):
        """Remove and return the `(key, value)` pair least frequently used."""

        if self._cache is None:
            raise KeyError("Cannot pop items from an empty cache.")

        if not self._cache:
            raise KeyError("Cache is empty.")

        most_frequent = min(self._cache, key=self._cache.get)
        key, value = most_frequent
        del self._cache[key]

        return (key, value)

def popitem(self):
