def isoparse(self, dt_str):
    date_pattern = re.compile(r'^(\d{4}-\d{2}-\d{2})')
    time_pattern = re.compile(r'(\d{2}(:\d{2}(:\d{2})?:\d{1,6}(?:\.\d+)?))')

    if date_pattern.match(dt_str):
        date = date_pattern.group(1)
        if time_pattern.match(dt_str):
            _, _, seconds_str = dt_str.partition(' ')
            if not seconds_str:
                seconds_str = '00'
            return parser.isoparse(date + 'T' + seconds_str)
        else:
            return parser.isoparse(date + 'T00:00:00')
    else:
        return parser.isoparse(dt_str)

def parse(self, timestr, default=None,
          ignoretz=False, tzinfos=None, **kwargs):
    if not isinstance(timestr, str):
        raise TypeError("timestr must be a string")

    if isinstance(timestr, bytes):
        raise TypeError("timestr must be a string")

    if not timestr:
        return default if default is not None else None

    if ignoretz:
        return parse(timestr)

    if tzinfos is None:
        tzinfos = {}

    if tzinfos not in [dict, function]:
        if isinstance(tzinfos, dict):
            for tz in tzinfos:
                if isinstance(tzinfos[tz], str):
                    if len(tzinfos[tz]) <= len('2000-01-01'):
                        tzinfos[tz] = datetime.timezone(timedelta(seconds=tzinfos[tz]))
                    elif re.match('^[-+]\d+$', tzinfos[tz]):
                        tzinfos[tz] = datetime.timezone(timedelta(seconds=int(tzinfos[tz])))
                    else:
                        tzinfos[tz] = tzinfo(tzinfos[tz])
        elif isinstance(tzinfos, function):
            def new_tzinfo(tzname, tzoffset):
                if isinstance(tz-offset, str):
                    if len(tz-offset) <= len('2000-01-01'):
                        return datetime.timezone(timedelta(seconds=tzoffset))
                    elif re.match('^[-+]\d+$', tzoffset):
                        return datetime.timezone(timedelta(seconds=int(tzoffset)))
                    else:
                        return tzinfo(tzoffset)
                return tzinfo(tzname, tzoffset)
            tzinfos = new_tzinfo

    try:
        localdate = parse(timestr, tzinfos=tzinfos, **kwargs)
        if not ignoretz:
            localdate = localdate.replace(tzinfo=None)
    except (ValueError, TypeError, OverflowError):
        localdate = None

    return localdate

