def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """

        if yaml_file is None:
            raise IRValidatorException("yaml_file argument must be supplied")

        try:
            with open(yaml_file, 'r') as f:
                data = yaml.safe_load(f)

        except Exception as e:
            raise IRValidatorException("There was a problem parsing the file. " + str(e))

        schema = json.load(open(cls.default_schema_file, 'r'))

        try:
            json_validate(data, schema)

        except ValidationError as ve:
            raise IRValidatorException("Validation error: " + ve.message)

        for field in cls.getMandatoryFields(schema):
            if field not in data:
                raise IRValidatorException("Missing field in YAML: " + field)

        return data

    @classmethod
    def getMandatoryFields(cls, schema):
        fields = []
        for key in schema.keys():
            if key.startswith('properties.'):
                if 'required' in schema[key] and schema[key]['required']:
                    fields.append(key[11:])
        return fields

    def add_validation_message(self, message):
        print("Validation error in " + message.file + ": " + message.message)

    def has_errors(self, file_path):
        return False

def _include_groups(self, parser_dict):
    """ Resolves the include dict directive in the spec files. """
    if 'includes' in parser_dict:
        for include_path in parser_dict['includes']:
            with open(include_path, 'r') as file:
                included_data = file.read()
                parsed_items = self._parse(include_data)
                for key, value in parsed_items.items():
                    parser_dict[key] = value

