def _get_conditionally_required_args(self, command_name, options_spec, args):
    console = Console()
    required_flags = set()

    for option in options_spec:
        for name, spec in option.items():
            if 'required_when' in spec:
                if spec['required_when'].in_argn():
                    required_flags.add(name)
                else:
                    try:
                        arg_index = spec['required_when']['arg_indices']
                        value = args[arg_index]
                        if value in spec['required_when'].values:
                            required_flags.add(name)
                    except (IndexError, KeyError):
                        console.log(f"Warning: Missing required option '{name}' for command '{command_name}'. It will not be prompted to the user if provided as part of command input.", style="yellow")
                        continue

    return required_flags

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, (list, dict)):
        raise ValueError("Input must be a list or a dictionary")

    for key, value in args.items():
        if not isinstance(value, str) or len(value) > self.max_length:
            raise ValueError(f"Argument '{key}' has a value of {value}, which is longer than the maximum allowed length of {self.max_length}")

def validate_choices_args(self, args):
