def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        """
        if not hasattr(args, 'min_value') or not hasattr(args, 'max_value'):
            raise TypeError("The 'min_value' and 'max_value' attributes must be set on the arguments.")

        if 'value' not in args:
            raise TypeError("The 'value' attribute must be set on the arguments.")

        if args['value'] < args['min_value'] or args['value'] > args['max_value']:
            raise ValueError("The value of the argument is out of the valid range.")

