def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    nested_args = {}
    control_args = {}

    for arg in args:
        if arg.startswith('--control-'):
            control_args[arg[len('--control-'):]] = True
        elif arg.startswith('--nested-'):
            nested_args[arg[len('--nested-'):]] = True
        elif arg.startswith('--custom-'):
            custom_args[arg[len('--custom-'):]] = arg
        else:
            raise ValueError(f"Unknown argument: {arg}")

    return control_args, nested_args

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments"""
    # defining a simple conversion dictionary based on the parser_type
    conversion_dict = {
        ' '--port': int,
        ' --host': str,
        ' --blotter': str,
        ' --nopass': bool
    }

    # If set, update the values_dict with the appropriate conversion
    if parser_name in conversion_dict:
        for key, value in values_dict.items():
            if key.startswith(parser_name):
                try:
                    values_dict[key] = conversion_dict[parser_name](value)
                except ValueError:
                    print(f"Invalid value for {key}: expected {conversion_dict[parser_name]}")
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    flatten_dict = {}
    for root, dirs, files in os.walk(plugin_dir):
        for file in files:
            if file.endswith('.json'):
                json_file_path = os.path.join(root, file)
                with open(json_file_path) as file:
                    plugin_spec = json.load(file)
                    for key, value in plugin_spec.items():
                        path = os.path.join(root, file)
                        flatten_dict[(root, file, key)] = value
    return flatten_dict

